1	/**
2	 * Wrapper hook around the toggleHabit mutation that automatically injects
3	 * the user's timezone so server-side streak calculations use local time
4	 * instead of UTC.
5	 *
6	 * Edge case guard: Timezone is re-calculated on every toggle to handle
7	 * timezone switching (e.g., user travels across timezones).
8	 *
9	 * @returns Toggle function that accepts date and habitId
10	 *
11	 * @example
12	 * ```ts
13	 * const toggleHabit = useToggleHabitWithTimezone();
14	 * await toggleHabit({ date: '2024-01-15', habitId: 'abc123' });
15	 * ```
16	 */
17	import { useCallback } from 'react';
18	import { useMutation } from 'convex/react';
19	import { api } from '../../convex/_generated/api';
20	import type { Id } from '../../convex/_generated/dataModel';
21	import { getUserTimezone } from '../utils/timezone';
22	
23	export function useToggleHabitWithTimezone() {
24	  const rawToggle = useMutation(api.habits.toggleHabit);
25	
26	  const toggleHabit = useCallback(
27	    (args: { date: string; habitId: Id<'habits'> }) => {
28	      // Re-read timezone on every toggle to handle timezone switching
29	      const currentTimezone = getUserTimezone();
30	      return rawToggle({ ...args, timezone: currentTimezone });
31	    },
32	    [rawToggle]
33	  ) as typeof rawToggle;
34	
35	  return toggleHabit;
36	}
37	
38	export default useToggleHabitWithTimezone;
39

